from checks import available
def reserve(stock, requests):
    reqs = {}
    for sku, quantity in requests:
        if quantity <= 0: raise ValueError('nonpositive quantity')
        if sku in reqs: reqs[sku] += quantity
        else: reqs[sku] = quantity
    for sku, quantity in reqs.items():
        if not available(stock, sku, quantity): raise ValueError('unavailable')
        stock[sku] -= quantity
    return stock

